                this.setupCamera();
                this.setupLights();
                this.createGlobe();
                this.setupControls();
                this.animate();
            }

            setupRenderer() {
                this.renderer.setSize(window.innerWidth, window.innerHeight);
                this.renderer.setPixelRatio(window.devicePixelRatio);
                this.renderer.setClearColor(0x667eea, 1);
