                const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
                this.scene.add(ambientLight);

                // Directional light (sun)
                const directionalLight = new THREE.DirectionalLight(0xffffff, 0.9);
                directionalLight.position.set(5, 10, 7);
                directionalLight.castShadow = true;
                directionalLight.shadow.mapSize.width = 2048;
                directionalLight.shadow.mapSize.height = 2048;
                this.scene.add(directionalLight);

                // Hemisphere light (sky)
                const hemisphereLight = new THREE.HemisphereLight(0x87ceeb, 0x87ceeb, 0.5);
                this.scene.add(hemisphereLight);
            }

            createGlobe() {
                // Outer glass sphere with semi-transparency
                const sphereGeometry = new THREE.IcosahedronGeometry(3, 40);
                const sphereMaterial = new THREE.MeshPhongMaterial({
                    color: 0xb3e5fc,
                    emissive: 0x000000,
                    specular: 0xffffff,
                    shininess: 120,
                    transparent: true,
                    opacity: 0.3,
                    wireframe: false,
                    side: THREE.DoubleSide
                });
                this.globeSphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
                this.scene.add(this.globeSphere);

                // Interior group (everything inside the globe)
                this.interiorGroup = new THREE.Group();
                this.scene.add(this.interiorGroup);

                // Wooden base
                const baseGeometry = new THREE.CylinderGeometry(3.2, 3.5, 0.7, 32);
                const baseMaterial = new THREE.MeshPhongMaterial({
                    color: 0x8B4513,
                    shininess: 30
                });
                const base = new THREE.Mesh(baseGeometry, baseMaterial);
                base.castShadow = true;
                base.position.y = -3.35;
                this.scene.add(base);

                // Create mountain
                this.createMountain();

                // Create snow
                this.createSnow();

                // Add decorative rocks
                this.addRocks();
            }

            createMountain() {
                // Main snow-capped mountain
                const mountainGeometry = new THREE.ConeGeometry(1.3, 2.4, 32);
                const mountainMaterial = this.createMountainMaterial();

                this.mountain = new THREE.Mesh(mountainGeometry, mountainMaterial);
                this.mountain.castShadow = true;
                this.mountain.position.y = -0.2;
                this.interiorGroup.add(this.mountain);

                // Secondary peaks for visual interest
                const smallPeakGeometry = new THREE.ConeGeometry(0.45, 1.2, 24);
                const snowMaterial = new THREE.MeshPhongMaterial({
                    color: 0xffffff,
                    shininess: 90
                });

                const peak1 = new THREE.Mesh(smallPeakGeometry, snowMaterial);
                peak1.castShadow = true;
                peak1.position.set(0.7, 0.1, 0.6);
                peak1.scale.set(0.65, 0.65, 0.65);
                this.interiorGroup.add(peak1);

                const peak2 = new THREE.Mesh(smallPeakGeometry, snowMaterial);
                peak2.castShadow = true;
                peak2.position.set(-0.8, 0.2, -0.5);
                peak2.scale.set(0.55, 0.55, 0.55);
                this.interiorGroup.add(peak2);
            }

            createMountainMaterial() {
                // Create canvas texture for snow-capped mountain gradient
                const canvas = document.createElement('canvas');
                canvas.width = 256;
                canvas.height = 512;
                const ctx = canvas.getContext('2d');

                // Create gradient: white snow at top, gray/brown rock at bottom
                const gradient = ctx.createLinearGradient(0, 0, 0, 512);
                gradient.addColorStop(0, '#FFFFFF');      // Pure snow at peak
                gradient.addColorStop(0.25, '#F8F8FF');   // Very light blue-white
                gradient.addColorStop(0.35, '#E8E8E8');   // Light gray
                gradient.addColorStop(0.5, '#A0A0A0');    // Medium gray
                gradient.addColorStop(0.7, '#6B6B5C');    // Dark gray-brown
                gradient.addColorStop(1, '#5C4836');      // Dark brown

                ctx.fillStyle = gradient;
                ctx.fillRect(0, 0, 256, 512);

                // Add subtle texture with noise
                const imageData = ctx.getImageData(0, 0, 256, 512);
                const data = imageData.data;
                for (let i = 0; i < data.length; i += 4) {
                    const noise = (Math.random() - 0.5) * 20;
                    data[i] += noise;     // R
                    data[i + 1] += noise; // G
                    data[i + 2] += noise; // B
