                    positions[i * 3] = (Math.random() - 0.5) * 5.5;
                    positions[i * 3 + 1] = (Math.random() - 0.5) * 5.5;
                    positions[i * 3 + 2] = (Math.random() - 0.5) * 5.5;

                    // Velocities - mostly downward with slight horizontal drift
